import React, { useState, useEffect } from 'react';
import { FaFilm, FaEdit, FaTrash, FaCheck } from 'react-icons/fa';
import './StreamList.css';

function StreamList() {
  const [input, setInput] = useState('');
  const [movies, setMovies] = useState(() => {
    const storedMovies = localStorage.getItem('movies');
    return storedMovies ? JSON.parse(storedMovies) : [];
  });
  const [editId, setEditId] = useState(null);
  const [editText, setEditText] = useState('');
  const [notificationMessage, setNotificationMessage] = useState('');

  // Persist movies to Local Storage whenever movies state changes.
  useEffect(() => {
    localStorage.setItem('movies', JSON.stringify(movies));
  }, [movies]);

  // Function to search TMDB for a given query.
  const searchMovieOnTMDB = async (query) => {
    const API_KEY = "a811f5125a024eaec27cf8e31e3e1fb6";
    const url = `https://api.themoviedb.org/3/search/movie?api_key=${API_KEY}&query=${encodeURIComponent(query)}`;
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error('Error fetching movie from TMDB');
    }
    const data = await response.json();
    return data.results;
  };

  // Handler for form submission.
  const handleSubmit = async (event) => {
    event.preventDefault();
    const trimmedInput = input.trim();
    if (!trimmedInput) return;

    try {
      const results = await searchMovieOnTMDB(trimmedInput);

      // If no results at all, add movie as not validated.
      if (!results || results.length === 0) {
        setNotificationMessage("No movie found. Adding movie anyway.");
        setTimeout(() => setNotificationMessage(''), 3000);
        setMovies([
          ...movies,
          {
            id: Date.now(),
            name: trimmedInput,
            verified: false,
            tmdbData: null,
          },
        ]);
        setInput('');
        return;
      }

      // Try to find an exact match (case-insensitive).
      let matchingMovie = results.find(
        (movie) => movie.title.toLowerCase() === trimmedInput.toLowerCase()
      );

      // If no exact match, try partial matches.
      if (!matchingMovie) {
        const partialMatches = results.filter((movie) =>
          movie.title.toLowerCase().includes(trimmedInput.toLowerCase())
        );
        // Define a threshold: user's input should be at least 50% of the movie title length.
        const MATCH_THRESHOLD = 0.5;
        const validPartialMatches = partialMatches.filter(
          (movie) => trimmedInput.length / movie.title.length >= MATCH_THRESHOLD
        );
        if (validPartialMatches.length > 0) {
          // Choose the movie with the highest ratio.
          matchingMovie = validPartialMatches.reduce((prev, curr) => {
            const prevRatio = trimmedInput.length / prev.title.length;
            const currRatio = trimmedInput.length / curr.title.length;
            return currRatio > prevRatio ? curr : prev;
          });
        }
      }

      if (!matchingMovie) {
        setNotificationMessage("Movie not validated by TMDB. Adding movie anyway.");
        setTimeout(() => setNotificationMessage(''), 3000);
        setMovies([
          ...movies,
          {
            id: Date.now(),
            name: trimmedInput,
            verified: false,
            tmdbData: null,
          },
        ]);
      } else {
        setMovies([
          ...movies,
          {
            id: Date.now(),
            name: matchingMovie.title,
            verified: true,
            tmdbData: matchingMovie,
          },
        ]);
      }
      setInput('');
    } catch (error) {
      setNotificationMessage("Error validating movie. Please try again later.");
      setTimeout(() => setNotificationMessage(''), 3000);
    }
  };

  const handleDelete = (id) => {
    setMovies(movies.filter((movie) => movie.id !== id));
  };

  const handleComplete = (id) => {
    setMovies(
      movies.map((movie) =>
        movie.id === id ? { ...movie, completed: !movie.completed } : movie
      )
    );
  };

  const handleEdit = (id, name) => {
    setEditId(id);
    setEditText(name);
  };

  const handleEditSubmit = (event) => {
    event.preventDefault();
    setMovies(
      movies.map((movie) =>
        movie.id === editId ? { ...movie, name: editText } : movie
      )
    );
    setEditId(null);
    setEditText('');
  };

  return (
    <div className="streamlist-container">
      <h1>StreamList - Your Movie/TV Show List</h1>
      <form onSubmit={handleSubmit} className="input-form">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Add a movie/show..."
        />
        <button type="submit">
          <FaFilm /> Add
        </button>
      </form>

      {/* Render the list of movies on the homepage */}
      <ul className="movie-list">
        {movies.map((movie) => (
          <li key={movie.id} className={movie.completed ? "completed" : ""}>
            {editId === movie.id ? (
              <form onSubmit={handleEditSubmit} className="edit-form">
                <input
                  type="text"
                  value={editText}
                  onChange={(e) => setEditText(e.target.value)}
                />
                <button type="submit">
                  <FaCheck />
                </button>
              </form>
            ) : (
              <>
                <span>
                  {movie.name}{' '}
                  {movie.verified && <span className="verified-badge">Verified</span>}
                </span>
                <div className="actions">
                  <button onClick={() => handleComplete(movie.id)}>
                    <FaCheck />
                  </button>
                  <button onClick={() => handleEdit(movie.id, movie.name)}>
                    <FaEdit />
                  </button>
                  <button onClick={() => handleDelete(movie.id)}>
                    <FaTrash />
                  </button>
                </div>
              </>
            )}
          </li>
        ))}
      </ul>

      {/* Display the notification message at the bottom */}
      {notificationMessage && (
        <div
          className="notification-message"
          style={{ textAlign: "center", marginTop: "20px", color: "#ff0000" }}
        >
          {notificationMessage}
        </div>
      )}
    </div>
  );
}

export default StreamList;
